INSERT INTO subscription_tier (tier_id, tier_name, price, max_resolution, max_devices, description, is_active) VALUES
('d740460f-dc7c-5cd5-b609-2685aba941d8', 'Basic', 49000.00, '720p', 1, 'Gói Cơ bản (Basic): Xem toàn bộ thư viện phim, độ phân giải HD 720p, tối đa 1 thiết bị đồng thời.', TRUE),
('c4bb8244-a194-538b-8384-2cac30b5ae41', 'Plus', 79000.00, '1080p', 2, 'Gói Tiêu chuẩn (Plus): Xem toàn bộ thư viện phim, độ phân giải Full HD 1080p, tối đa 2 thiết bị đồng thời.', TRUE),
('0f738876-5cfd-53e5-8090-19afaf2a8b9b', 'Pro', 119000.00, '4K', 4, 'Gói Cao cấp (Pro): Xem toàn bộ thư viện phim, chất lượng 4K UHD, tối đa 4 thiết bị đồng thời.', TRUE);
INSERT INTO genre (genre_id, name, description) VALUES
('fc070ac8-b0bb-53da-9541-4bbbb6b3be67', 'Hành động (Action)', 'Phim hành động kịch tính với các pha võ thuật, rượt đuổi và phiêu lưu mạo hiểm.'),
('3dce94ee-5465-5df6-bbf4-108715315b63', 'Khoa học Viễn tưởng (Sci-Fi)', 'Khám phá tương lai, công nghệ cao, vũ trụ và đa vũ trụ.'),
('99692fb6-a0b7-555d-a63e-2703a4ec05af', 'Chính kịch (Drama)', 'Khai thác chiều sâu tâm lý nhân vật và các mối quan hệ xã hội.'),
('4bd07429-b6f0-5d2b-a691-602b619db14c', 'Hài hước (Comedy)', 'Nội dung giải trí nhẹ nhàng, mang lại tiếng cười sảng khoái.'),
('0f167a5a-ac00-5932-b47f-0570639e3035', 'Kinh dị (Horror)', 'Phim rùng rợn, yếu tố siêu nhiên và tâm lý giật gân.'),
('bdf8958a-176c-5e7f-a385-0ed1394e9aa0', 'Tình cảm Lãng mạn (Romance)', 'Những câu chuyện tình yêu cảm động và sâu sắc.'),
('12c666e6-aa94-53bf-b375-d0efcfdbc646', 'Tài liệu (Documentary)', 'Phim tài liệu khám phá thiên nhiên, lịch sử, khoa học và con người.'),
('fdd7f778-d203-55ec-9683-655d4eefb396', 'Hoạt hình (Animation)', 'Phim hoạt hình 2D/3D dành cho gia đình, trẻ em và mọi lứa tuổi.'),
('00d4b797-e1f6-51fa-8974-0aa0cf05a35f', 'Hình sự Tội phạm (Crime)', 'Điều tra phá án, thế giới ngầm và cuộc đấu trí pháp luật.'),
('2c10e7b9-9daa-5442-a1d4-73278d51e781', 'Bí ẩn Giật gân (Thriller)', 'Cốt truyện gay cấn, nhiều nút thắt bất ngờ đến phút cuối.'),
('3efe7519-a9b8-59bb-9bb3-01e6c2fe021c', 'Giả tưởng (Fantasy)', 'Thế giới phép thuật, thần thoại và sử thi kỳ ảo.'),
('03adc7a0-8a43-5a08-affc-df24bf0fe6b7', 'Gia đình (Family)', 'Nội dung ấm áp, giáo dục và an toàn cho trẻ em cùng gia đình.'),
('de990018-684f-5323-af62-a938542d5adf', 'Lịch sử Chiến tranh (History)', 'Tái hiện các sự kiện lịch sử và chiến dịch quân sự hào hùng.'),
('899c66bb-87d7-51c4-9566-dac3987b209e', 'Âm nhạc (Music)', 'Phim ca nhạc, tiểu sử nghệ sĩ và các buổi hòa nhạc đặc sắc.'),
('be680ee9-bed1-5008-95e1-5a24690b6a28', 'Thể thao (Sport)', 'Hành trình vượt lên chính mình của các vận động viên đỉnh cao.'),
('404c0f20-ff03-53c5-afb9-d0ce460a4cfa', 'Phiêu lưu (Adventure)', 'Hành trình khám phá những vùng đất mới và kho báu bí ẩn.');
