-- =============================================================================
-- KỊCH BẢN TRIỂN KHAI CƠ SỞ DỮ LIỆU POSTGRESQL (DDL, DML 3.000 PHIM, TRIGGERS,
-- VIEWS, INDEXES, 12 TRUY VẤN NÂNG CAO, TEST CASES & PHÂN QUYỀN RBAC)
-- Dự án: #2 - Nền tảng Xem phim Theo yêu cầu (On-Demand Streaming Platform - Mini-Netflix)
-- Nhóm thực hiện: Nhóm 10 (Nguyễn Thị Ái Diễm, Nguyễn Ngọc Quỳnh Như, Lê Minh Thư)
-- Tuân thủ tiêu chuẩn: SQLStyle.guide (Simon Holywell) & Google SQL Style Guide
-- Hệ quản trị CSDL mục tiêu: PostgreSQL 15+
-- =============================================================================

BEGIN;

-- Kích hoạt phần mở rộng sinh khóa UUID tự động trên PostgreSQL
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- =============================================================================
-- PHẦN 1: NGÔN NGỮ ĐỊNH NGHĨA DỮ LIỆU (DATA DEFINITION LANGUAGE - DDL: 13 BẢNG)
-- =============================================================================

-- 1.1. Bảng Gói đăng ký (subscription_tier)
CREATE TABLE subscription_tier (
    tier_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tier_name VARCHAR(50) NOT NULL UNIQUE
        CONSTRAINT chk_subscription_tier_name
        CHECK (tier_name IN ('Basic', 'Plus', 'Pro')),
    price NUMERIC(10, 2) NOT NULL
        CONSTRAINT chk_subscription_tier_price
        CHECK (price >= 0),
    max_resolution VARCHAR(20) NOT NULL
        CONSTRAINT chk_subscription_tier_resolution
        CHECK (max_resolution IN ('720p', '1080p', '4K')),
    max_devices SMALLINT NOT NULL
        CONSTRAINT chk_subscription_tier_devices
        CHECK (max_devices BETWEEN 1 AND 10),
    description TEXT NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 1.2. Bảng Người dùng (user_account / "user")
CREATE TABLE "user" (
    user_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tier_id UUID NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE
        CONSTRAINT chk_user_email_format
        CHECK (email ~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$'),
    password_hash VARCHAR(255) NOT NULL,
    full_name VARCHAR(120) NOT NULL,
    phone VARCHAR(20) NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'active'
        CONSTRAINT chk_user_status
        CHECK (status IN ('active', 'inactive', 'suspended')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_user_subscription_tier
        FOREIGN KEY (tier_id)
        REFERENCES subscription_tier (tier_id)
        ON DELETE RESTRICT
        ON UPDATE CASCADE
);

-- 1.3. Bảng Hồ sơ cá nhân (profile - Thực thể yếu phụ thuộc vào "user")
CREATE TABLE profile (
    profile_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL,
    name VARCHAR(60) NOT NULL,
    avatar_url VARCHAR(500) NULL DEFAULT 'file:///D:/Ai%20Diem/Giao_trinh/CSDL/Mini-Netflix/avt_default.jpg',
    is_child BOOLEAN NOT NULL DEFAULT FALSE,
    parental_pin VARCHAR(255) NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_profile_user_name
        UNIQUE (user_id, name),
    CONSTRAINT fk_profile_user
        FOREIGN KEY (user_id)
        REFERENCES "user" (user_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
);

-- 1.4. Bảng Thể loại (genre)
CREATE TABLE genre (
    genre_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(80) NOT NULL UNIQUE,
    description TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 1.5. Bảng Phim bộ (tv_series)
CREATE TABLE tv_series (
    series_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    title VARCHAR(255) NOT NULL,
    title_original VARCHAR(255) NOT NULL,
    studio VARCHAR(120) NOT NULL,
    description TEXT NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ongoing'
        CONSTRAINT chk_tv_series_status
        CHECK (status IN ('ongoing', 'completed', 'canceled')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 1.6. Bảng Mùa phim (season - Thực thể yếu phụ thuộc vào tv_series)
CREATE TABLE season (
    season_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    series_id UUID NOT NULL,
    season_number SMALLINT NOT NULL
        CONSTRAINT chk_season_number_positive
        CHECK (season_number >= 1),
    title VARCHAR(150) NOT NULL,
    description TEXT NULL,
    release_year SMALLINT NOT NULL
        CONSTRAINT chk_season_release_year
        CHECK (release_year BETWEEN 1900 AND 2030),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_season_series_number
        UNIQUE (series_id, season_number),
    CONSTRAINT fk_season_tv_series
        FOREIGN KEY (series_id)
        REFERENCES tv_series (series_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
);

-- 1.7. Bảng Siêu lớp Nội dung (content - Superclass)
CREATE TABLE content (
    content_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    title VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    release_year SMALLINT NOT NULL
        CONSTRAINT chk_content_release_year
        CHECK (release_year BETWEEN 1900 AND 2030),
    thumbnail_url VARCHAR(500) NOT NULL,
    age_rating VARCHAR(15) NOT NULL
        CONSTRAINT chk_content_age_rating
        CHECK (age_rating IN ('G', 'PG', 'PG-13', 'R', 'NC-17')),
    content_type VARCHAR(15) NOT NULL
        CONSTRAINT chk_content_type_discriminator
        CHECK (content_type IN ('MOVIE', 'EPISODE')),
    popularity NUMERIC(8, 2) NOT NULL DEFAULT 0.00
        CONSTRAINT chk_content_popularity
        CHECK (popularity >= 0),
    is_published BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 1.8. Bảng Lớp con Phim lẻ (movie - Subclass kế thừa từ content)
CREATE TABLE movie (
    content_id UUID PRIMARY KEY,
    duration SMALLINT NOT NULL
        CONSTRAINT chk_movie_duration_positive
        CHECK (duration > 0),
    video_url VARCHAR(500) NOT NULL,
    director_name VARCHAR(150) NOT NULL,
    CONSTRAINT fk_movie_content
        FOREIGN KEY (content_id)
        REFERENCES content (content_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
);

-- 1.9. Bảng Lớp con Tập phim (episode - Subclass kế thừa từ content & thuộc season)
CREATE TABLE episode (
    content_id UUID PRIMARY KEY,
    season_id UUID NOT NULL,
    episode_number SMALLINT NOT NULL
        CONSTRAINT chk_episode_number_positive
        CHECK (episode_number >= 1),
    duration SMALLINT NOT NULL
        CONSTRAINT chk_episode_duration_positive
        CHECK (duration > 0),
    video_url VARCHAR(500) NOT NULL,
    release_date DATE NOT NULL,
    CONSTRAINT uq_episode_season_number
        UNIQUE (season_id, episode_number),
    CONSTRAINT fk_episode_content
        FOREIGN KEY (content_id)
        REFERENCES content (content_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE,
    CONSTRAINT fk_episode_season
        FOREIGN KEY (season_id)
        REFERENCES season (season_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
);

-- 1.10. Bảng liên kết Nội dung - Thể loại (content_genre - M:N)
CREATE TABLE content_genre (
    content_id UUID NOT NULL,
    genre_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_content_genre
        PRIMARY KEY (content_id, genre_id),
    CONSTRAINT fk_content_genre_content
        FOREIGN KEY (content_id)
        REFERENCES content (content_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE,
    CONSTRAINT fk_content_genre_genre
        FOREIGN KEY (genre_id)
        REFERENCES genre (genre_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
);

-- 1.11. Bảng Lịch sử xem (watch_history - M:N)
CREATE TABLE watch_history (
    history_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    profile_id UUID NOT NULL,
    content_id UUID NOT NULL,
    watched_percent NUMERIC(5, 2) NOT NULL DEFAULT 0.00
        CONSTRAINT chk_watch_history_percent
        CHECK (watched_percent BETWEEN 0.00 AND 100.00),
    watched_duration INT NOT NULL DEFAULT 0
        CONSTRAINT chk_watch_history_duration
        CHECK (watched_duration >= 0),
    device_type VARCHAR(30) NOT NULL
        CONSTRAINT chk_watch_history_device
        CHECK (device_type IN ('Web Browser', 'Smart TV', 'Mobile iOS', 'Mobile Android', 'Tablet')),
    last_watched_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_watch_history_profile_content
        UNIQUE (profile_id, content_id),
    CONSTRAINT fk_watch_history_profile
        FOREIGN KEY (profile_id)
        REFERENCES profile (profile_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE,
    CONSTRAINT fk_watch_history_content
        FOREIGN KEY (content_id)
        REFERENCES content (content_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
);

-- 1.12. Bảng Danh sách xem sau (watch_list - M:N)
CREATE TABLE watch_list (
    list_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    profile_id UUID NOT NULL,
    content_id UUID NOT NULL,
    added_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_watch_list_profile_content
        UNIQUE (profile_id, content_id),
    CONSTRAINT fk_watch_list_profile
        FOREIGN KEY (profile_id)
        REFERENCES profile (profile_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE,
    CONSTRAINT fk_watch_list_content
        FOREIGN KEY (content_id)
        REFERENCES content (content_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
);

-- 1.13. Bảng Đánh giá & Điểm số (review - M:N)
CREATE TABLE review (
    review_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    profile_id UUID NOT NULL,
    content_id UUID NOT NULL,
    rating SMALLINT NOT NULL
        CONSTRAINT chk_review_rating_range
        CHECK (rating BETWEEN 1 AND 5),
    comment TEXT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_review_profile_content
        UNIQUE (profile_id, content_id),
    CONSTRAINT fk_review_profile
        FOREIGN KEY (profile_id)
        REFERENCES profile (profile_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE,
    CONSTRAINT fk_review_content
        FOREIGN KEY (content_id)
        REFERENCES content (content_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
);

-- =============================================================================
-- PHẦN 2: CHỈ MỤC TỐI ƯU HÓA HIỆU NĂNG TRUY VẤN DƯỚI 200MS (INDEXES - NFR-02)
-- =============================================================================

CREATE INDEX idx_user_tier_status
    ON "user" (tier_id, status);

CREATE INDEX idx_profile_user_child
    ON profile (user_id, is_child);

CREATE INDEX idx_content_type_year_rating
    ON content (content_type, release_year DESC, age_rating)
    WHERE is_published = TRUE;

CREATE INDEX idx_content_title_search
    ON content (LOWER(title) varchar_pattern_ops);

CREATE INDEX idx_episode_season_num
    ON episode (season_id, episode_number);

CREATE INDEX idx_content_genre_genre_id
    ON content_genre (genre_id, content_id);

CREATE INDEX idx_watch_history_profile_recent
    ON watch_history (profile_id, last_watched_at DESC);

CREATE INDEX idx_review_content_rating
    ON review (content_id, rating);

-- =============================================================================
-- PHẦN 3: KHUNG NHÌN (VIEWS) VÀ TRÌNH KÍCH HOẠT RÀNG BUỘC (TRIGGERS)
-- =============================================================================

-- 3.1. View 1: Danh mục Nội dung Hợp nhất kèm Điểm đánh giá Trung bình (vw_content_catalog_summary)
CREATE OR REPLACE VIEW vw_content_catalog_summary AS
SELECT
    c.content_id,
    c.title,
    c.content_type,
    c.release_year,
    c.age_rating,
    c.popularity,
    COALESCE(m.duration, e.duration) AS duration_minutes,
    m.director_name,
    ts.title AS series_title,
    s.season_number,
    e.episode_number,
    COUNT(DISTINCT r.review_id) AS total_reviews,
    ROUND(COALESCE(AVG(r.rating), 0.00), 2) AS avg_rating
FROM content AS c
LEFT JOIN movie AS m
    ON c.content_id = m.content_id
LEFT JOIN episode AS e
    ON c.content_id = e.content_id
LEFT JOIN season AS s
    ON e.season_id = s.season_id
LEFT JOIN tv_series AS ts
    ON s.series_id = ts.series_id
LEFT JOIN review AS r
    ON c.content_id = r.content_id
WHERE c.is_published = TRUE
GROUP BY
    c.content_id,
    c.title,
    c.content_type,
    c.release_year,
    c.age_rating,
    c.popularity,
    m.duration,
    e.duration,
    m.director_name,
    ts.title,
    s.season_number,
    e.episode_number;

-- 3.2. View 2: Danh sách "Xem tiếp" (Continue Watching) cho từng Hồ sơ (vw_profile_continue_watching)
CREATE OR REPLACE VIEW vw_profile_continue_watching AS
SELECT
    wh.profile_id,
    p.name AS profile_name,
    wh.content_id,
    c.title AS content_title,
    c.content_type,
    c.thumbnail_url,
    wh.watched_percent,
    wh.watched_duration,
    wh.device_type,
    wh.last_watched_at
FROM watch_history AS wh
INNER JOIN profile AS p
    ON wh.profile_id = p.profile_id
INNER JOIN content AS c
    ON wh.content_id = c.content_id
WHERE wh.watched_percent > 0.00
  AND wh.watched_percent < 95.00;

-- 3.3. Trigger 1: Kiểm soát Giới hạn Tối đa 5 Hồ sơ trên mỗi Người dùng (FR-02)
CREATE OR REPLACE FUNCTION fn_enforce_profile_quota()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_current_count INT;
BEGIN
    SELECT COUNT(*)
    INTO v_current_count
    FROM profile
    WHERE user_id = NEW.user_id;

    IF v_current_count >= 5 THEN
        RAISE EXCEPTION 'Vi phạm FR-02: Mỗi Người dùng (USER) chỉ được phép tạo tối đa 5 Hồ sơ (PROFILE). Hiện tại đã đạt % hồ sơ.', v_current_count
            USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_enforce_profile_quota
BEFORE INSERT ON profile
FOR EACH ROW
EXECUTE FUNCTION fn_enforce_profile_quota();

-- 3.4. Trigger 2: Bảo vệ Hồ sơ Trẻ em khỏi Nội dung Giới hạn Độ tuổi R / NC-17 / PG-13 (FR-03)
CREATE OR REPLACE FUNCTION fn_enforce_child_profile_age_rating()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_is_child BOOLEAN;
    v_age_rating VARCHAR(15);
BEGIN
    SELECT is_child
    INTO v_is_child
    FROM profile
    WHERE profile_id = NEW.profile_id;

    SELECT age_rating
    INTO v_age_rating
    FROM content
    WHERE content_id = NEW.content_id;

    IF v_is_child = TRUE AND v_age_rating NOT IN ('G', 'PG') THEN
        RAISE EXCEPTION 'Vi phạm FR-03: Hồ sơ Trẻ em (is_child = TRUE) không được phép truy cập hoặc lưu Nội dung có giới hạn độ tuổi %.', v_age_rating
            USING ERRCODE = 'P0002';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_child_safety_watch_history
BEFORE INSERT OR UPDATE ON watch_history
FOR EACH ROW
EXECUTE FUNCTION fn_enforce_child_profile_age_rating();

CREATE TRIGGER trg_child_safety_watch_list
BEFORE INSERT OR UPDATE ON watch_list
FOR EACH ROW
EXECUTE FUNCTION fn_enforce_child_profile_age_rating();

-- 3.5. Trigger 3: Thực thi Ràng buộc Tách rời EER (Disjoint Constraint) cho MOVIE và EPISODE (FR-04)
CREATE OR REPLACE FUNCTION fn_enforce_disjoint_content_subclass()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_content_type VARCHAR(15);
BEGIN
    SELECT content_type
    INTO v_content_type
    FROM content
    WHERE content_id = NEW.content_id;

    IF TG_TABLE_NAME = 'movie' AND v_content_type <> 'MOVIE' THEN
        RAISE EXCEPTION 'Vi phạm FR-04 (Disjoint EER): Bản ghi content_id % có content_type = % nên không thể chèn vào bảng MOVIE.', NEW.content_id, v_content_type
            USING ERRCODE = 'P0003';
    ELSIF TG_TABLE_NAME = 'episode' AND v_content_type <> 'EPISODE' THEN
        RAISE EXCEPTION 'Vi phạm FR-04 (Disjoint EER): Bản ghi content_id % có content_type = % nên không thể chèn vào bảng EPISODE.', NEW.content_id, v_content_type
            USING ERRCODE = 'P0003';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_check_movie_disjoint
BEFORE INSERT OR UPDATE ON movie
FOR EACH ROW
EXECUTE FUNCTION fn_enforce_disjoint_content_subclass();

CREATE TRIGGER trg_check_episode_disjoint
BEFORE INSERT OR UPDATE ON episode
FOR EACH ROW
EXECUTE FUNCTION fn_enforce_disjoint_content_subclass();

-- =============================================================================
-- PHẦN 4: DỮ LIỆU THỰC TẾ QUY MÔ LỚN (DML: 3.000 NỘI DUNG PHIM LẺ & TẬP PHIM)
-- Bao gồm: 3 Gói cước, 16 Thể loại, 150 Phim bộ, 300 Mùa phim, 1.500 Phim lẻ,
-- 1.500 Tập phim (= 3.000 CONTENT), 120 Người dùng, 300 Hồ sơ, Lịch sử & Đánh giá
-- =============================================================================

-- 4.1. Nạp 3 Gói đăng ký chuẩn của Nhóm 10 (Basic, Plus, Pro)

-- 4.2. Nạp 16 Thể loại phim (genre)

-- 4.3. Nạp 120 Người dùng ("user")

-- 4.4. Nạp 300 Hồ sơ cá nhân (profile: từ 1 đến 4 hồ sơ mỗi User, có hồ sơ trẻ em)

-- 4.5. Nạp 150 Phim bộ (tv_series)

-- 4.6. Nạp 300 Mùa phim (season: mỗi Phim bộ gồm 2 Mùa)

-- 4.7. Nạp 3.000 Bản ghi Siêu lớp Nội dung (content: 1.500 MOVIE + 1.500 EPISODE)






-- 4.8. Nạp 1.500 Bản ghi Lớp con Phim lẻ (movie)



-- 4.9. Nạp 1.500 Bản ghi Lớp con Tập phim (episode)



-- 4.10. Nạp 4.500 Bản ghi Phân loại Nội dung - Thể loại (content_genre)





-- 4.11. Nạp 600 Bản ghi Lịch sử xem (watch_history)

-- 4.12. Nạp 400 Bản ghi Danh sách xem sau (watch_list)

-- 4.13. Nạp 500 Bản ghi Đánh giá & Điểm số (review)

COMMIT;

-- =============================================================================
-- PHẦN 5: 12 TRUY VẤN NÂNG CAO & PHÂN TÍCH HIỆU NĂNG (ADVANCED QUERIES - MỤC 4.2)
-- =============================================================================

-- Truy vấn 1 (Multi-Table INNER/LEFT JOIN + Filtering):
-- Trích xuất danh sách "Xem tiếp" (Continue Watching) của một Hồ sơ cụ thể kèm thông tin Phim lẻ hoặc Tập phim/Mùa/Phim bộ
EXPLAIN ANALYZE
SELECT
    p.name AS profile_name,
    c.title AS content_title,
    c.content_type,
    COALESCE(ts.title, 'Phim Điện ảnh Độc lập') AS series_name,
    s.season_number,
    e.episode_number,
    wh.watched_percent,
    wh.device_type,
    wh.last_watched_at
FROM watch_history AS wh
INNER JOIN profile AS p
    ON wh.profile_id = p.profile_id
INNER JOIN content AS c
    ON wh.content_id = c.content_id
LEFT JOIN episode AS e
    ON c.content_id = e.content_id
LEFT JOIN season AS s
    ON e.season_id = s.season_id
LEFT JOIN tv_series AS ts
    ON s.series_id = ts.series_id
WHERE wh.watched_percent BETWEEN 5.00 AND 90.00
ORDER BY wh.last_watched_at DESC
LIMIT 20;

-- Truy vấn 2 (Aggregation + GROUP BY + HAVING):
-- Thống kê Top 10 Nội dung có điểm đánh giá trung bình cao nhất (tối thiểu 2 lượt đánh giá)
EXPLAIN ANALYZE
SELECT
    c.content_id,
    c.title,
    c.content_type,
    c.release_year,
    COUNT(r.review_id) AS review_count,
    ROUND(AVG(r.rating), 2) AS avg_rating_score
FROM content AS c
INNER JOIN review AS r
    ON c.content_id = r.content_id
GROUP BY
    c.content_id,
    c.title,
    c.content_type,
    c.release_year
HAVING COUNT(r.review_id) >= 2
ORDER BY
    avg_rating_score DESC,
    review_count DESC
LIMIT 10;

-- Truy vấn 3 (Window Function DENSE_RANK + Partition By Genre):
-- Xếp hạng Top 3 Nội dung phổ biến nhất trong từng Thể loại (GENRE)
WITH ranked_genre_content AS (
    SELECT
        g.name AS genre_name,
        c.title AS content_title,
        c.content_type,
        c.popularity,
        DENSE_RANK() OVER (
            PARTITION BY g.genre_id
            ORDER BY c.popularity DESC
        ) AS genre_rank
    FROM genre AS g
    INNER JOIN content_genre AS cg
        ON g.genre_id = cg.genre_id
    INNER JOIN content AS c
        ON cg.content_id = c.content_id
    WHERE c.is_published = TRUE
)
SELECT
    genre_name,
    genre_rank,
    content_title,
    content_type,
    popularity
FROM ranked_genre_content
WHERE genre_rank <= 3
ORDER BY
    genre_name ASC,
    genre_rank ASC;

-- Truy vấn 4 (Revenue & Subscription Tier Analytics - CTE + Aggregation):
-- Phân tích cơ cấu Người dùng, số lượng Hồ sơ và Doanh thu ước tính hàng tháng theo từng Gói đăng ký (Basic, Plus, Pro)
SELECT
    st.tier_name,
    st.price AS monthly_unit_price,
    st.max_resolution,
    st.max_devices,
    COUNT(DISTINCT u.user_id) AS active_subscribers,
    COUNT(p.profile_id) AS total_profiles,
    ROUND(COUNT(p.profile_id)::NUMERIC / NULLIF(COUNT(DISTINCT u.user_id), 0), 2) AS avg_profiles_per_user,
    (COUNT(DISTINCT u.user_id) * st.price) AS estimated_monthly_revenue_vnd
FROM subscription_tier AS st
LEFT JOIN "user" AS u
    ON st.tier_id = u.tier_id
   AND u.status = 'active'
LEFT JOIN profile AS p
    ON u.user_id = p.user_id
GROUP BY
    st.tier_id,
    st.tier_name,
    st.price,
    st.max_resolution,
    st.max_devices
ORDER BY st.price ASC;

-- Truy vấn 5 (Correlated Subquery):
-- Tìm các Phim lẻ (MOVIE) có thời lượng dài hơn thời lượng trung bình của tất cả các Phim lẻ phát hành cùng năm
SELECT
    c.title,
    c.release_year,
    m.duration,
    m.director_name
FROM content AS c
INNER JOIN movie AS m
    ON c.content_id = m.content_id
WHERE m.duration > (
    SELECT AVG(m2.duration)
    FROM content AS c2
    INNER JOIN movie AS m2
        ON c2.content_id = m2.content_id
    WHERE c2.release_year = c.release_year
)
ORDER BY
    c.release_year DESC,
    m.duration DESC
LIMIT 25;

-- Truy vấn 6 (TV Series Hierarchy Rollup - 4-Table Join + Aggregation):
-- Thống kê tổng số Mùa phim, tổng số Tập phim và tổng thời lượng phát sóng (phút) của từng Phim bộ (TV_SERIES)
SELECT
    ts.series_id,
    ts.title AS series_title,
    ts.studio,
    ts.status,
    COUNT(DISTINCT s.season_id) AS total_seasons,
    COUNT(e.content_id) AS total_episodes,
    COALESCE(SUM(e.duration), 0) AS total_series_duration_minutes
FROM tv_series AS ts
LEFT JOIN season AS s
    ON ts.series_id = s.series_id
LEFT JOIN episode AS e
    ON s.season_id = e.season_id
GROUP BY
    ts.series_id,
    ts.title,
    ts.studio,
    ts.status
ORDER BY
    total_episodes DESC,
    ts.title ASC
LIMIT 20;

-- Truy vấn 7 (Personalized Content Recommendation via Collaborative Genre Affinity - CTE):
-- Gợi ý các bộ phim chưa xem thuộc Thể loại yêu thích nhất của một Hồ sơ dựa trên Lịch sử xem
WITH fav_genre AS (
    SELECT
        cg.genre_id,
        COUNT(*) AS watch_count
    FROM watch_history AS wh
    INNER JOIN content_genre AS cg
        ON wh.content_id = cg.content_id
    WHERE wh.profile_id = (SELECT profile_id FROM profile LIMIT 1)
    GROUP BY cg.genre_id
    ORDER BY watch_count DESC
    LIMIT 1
)
SELECT
    c.content_id,
    c.title,
    c.content_type,
    c.age_rating,
    c.popularity
FROM content AS c
INNER JOIN content_genre AS cg
    ON c.content_id = cg.content_id
INNER JOIN fav_genre AS fg
    ON cg.genre_id = fg.genre_id
WHERE NOT EXISTS (
    SELECT 1
    FROM watch_history AS wh2
    WHERE wh2.profile_id = (SELECT profile_id FROM profile LIMIT 1)
      AND wh2.content_id = c.content_id
)
ORDER BY c.popularity DESC
LIMIT 10;

-- Truy vấn 8 (Watchlist Conversion Rate Analysis - LEFT JOIN + CASE Expression):
-- Tính tỷ lệ chuyển đổi từ Danh sách xem sau (WATCH_LIST) sang Lịch sử đã xem thực tế (WATCH_HISTORY) của từng Hồ sơ
SELECT
    p.profile_id,
    p.name AS profile_name,
    COUNT(wl.list_id) AS total_watchlist_items,
    COUNT(wh.history_id) AS watched_from_watchlist,
    ROUND(
        (COUNT(wh.history_id)::NUMERIC / NULLIF(COUNT(wl.list_id), 0)) * 100,
        2
    ) AS watchlist_conversion_rate_pct
FROM profile AS p
INNER JOIN watch_list AS wl
    ON p.profile_id = wl.profile_id
LEFT JOIN watch_history AS wh
    ON wl.profile_id = wh.profile_id
   AND wl.content_id = wh.content_id
GROUP BY
    p.profile_id,
    p.name
HAVING COUNT(wl.list_id) >= 2
ORDER BY watchlist_conversion_rate_pct DESC
LIMIT 15;

-- Truy vấn 9 (Device Telemetry Distribution):
-- Phân tích thị phần thiết bị phát trực tuyến (Smart TV, Web, Mobile...) và tiến độ xem trung bình trên từng thiết bị
SELECT
    wh.device_type,
    COUNT(wh.history_id) AS total_sessions,
    ROUND(AVG(wh.watched_percent), 2) AS avg_completion_percent,
    SUM(CASE WHEN wh.watched_percent >= 90.00 THEN 1 ELSE 0 END) AS completed_sessions
FROM watch_history AS wh
GROUP BY wh.device_type
ORDER BY total_sessions DESC;

-- Truy vấn 10 (Child Profile Safe Catalog Filtering - FR-03 Verification Query):
-- Truy xuất kho nội dung an toàn tuyệt đối dành riêng cho Hồ sơ Trẻ em (is_child = TRUE -> chỉ lấy age_rating IN ('G', 'PG'))
SELECT
    c.content_id,
    c.title,
    c.content_type,
    c.age_rating,
    c.release_year,
    STRING_AGG(g.name, ', ' ORDER BY g.name) AS genres
FROM content AS c
INNER JOIN content_genre AS cg
    ON c.content_id = cg.content_id
INNER JOIN genre AS g
    ON cg.genre_id = g.genre_id
WHERE c.is_published = TRUE
  AND c.age_rating IN ('G', 'PG')
GROUP BY
    c.content_id,
    c.title,
    c.content_type,
    c.age_rating,
    c.release_year
ORDER BY c.popularity DESC
LIMIT 20;

-- Truy vấn 11 (Binge-Watching Detection on TV Series):
-- Phát hiện các Hồ sơ xem từ 2 Tập phim trở lên của cùng một Mùa phim
SELECT
    p.profile_id,
    p.name AS profile_name,
    ts.title AS series_title,
    s.season_number,
    COUNT(DISTINCT e.content_id) AS episodes_watched_in_season,
    ROUND(AVG(wh.watched_percent), 2) AS avg_episode_progress
FROM watch_history AS wh
INNER JOIN profile AS p
    ON wh.profile_id = p.profile_id
INNER JOIN episode AS e
    ON wh.content_id = e.content_id
INNER JOIN season AS s
    ON e.season_id = s.season_id
INNER JOIN tv_series AS ts
    ON s.series_id = ts.series_id
GROUP BY
    p.profile_id,
    p.name,
    ts.series_id,
    ts.title,
    s.season_id,
    s.season_number
HAVING COUNT(DISTINCT e.content_id) >= 2
ORDER BY episodes_watched_in_season DESC;

-- Truy vấn 12 (Director Portfolio Performance Summary):
-- Thống kê năng suất đạo diễn (số lượng phim lẻ, thời lượng trung bình, độ phổ biến trung bình và điểm đánh giá trung bình)
SELECT
    m.director_name,
    COUNT(m.content_id) AS total_movies_directed,
    ROUND(AVG(m.duration), 1) AS avg_movie_duration_min,
    ROUND(AVG(c.popularity), 2) AS avg_popularity,
    ROUND(COALESCE(AVG(r.rating), 0.00), 2) AS avg_viewer_rating
FROM movie AS m
INNER JOIN content AS c
    ON m.content_id = c.content_id
LEFT JOIN review AS r
    ON c.content_id = r.content_id
GROUP BY m.director_name
ORDER BY
    total_movies_directed DESC,
    avg_popularity DESC;

-- =============================================================================
-- PHẦN 6: KIỂM SOÁT TRUY CẬP DỰA TRÊN VAI TRÒ (RBAC - MỤC 5.2)
-- =============================================================================

-- Tạo 4 nhóm quyền (Roles) theo chuẩn nguyên tắc Đặc quyền tối thiểu (Principle of Least Privilege)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'visitor_role') THEN
        CREATE ROLE visitor_role NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated_user_role') THEN
        CREATE ROLE authenticated_user_role NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'content_admin_role') THEN
        CREATE ROLE content_admin_role NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'system_dba_role') THEN
        CREATE ROLE system_dba_role NOLOGIN SUPERUSER;
    END IF;
END
$$;

-- Thu hồi toàn bộ quyền mặc định từ PUBLIC trước khi cấp quyền tường minh
REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA public FROM PUBLIC;

-- 1. Quyền của Khách truy cập (visitor_role): Chỉ được xem bảng giá gói cước (BR-01, FR-01)
GRANT SELECT ON TABLE subscription_tier TO visitor_role;

-- 2. Quyền của Người dùng đã đăng nhập (authenticated_user_role):
GRANT SELECT ON TABLE
    subscription_tier,
    genre,
    content,
    movie,
    tv_series,
    season,
    episode,
    content_genre,
    vw_content_catalog_summary,
    vw_profile_continue_watching
TO authenticated_user_role;

GRANT SELECT, UPDATE (full_name, phone, password_hash, updated_at)
    ON TABLE "user"
    TO authenticated_user_role;

GRANT SELECT, INSERT, UPDATE, DELETE
    ON TABLE profile, watch_history, watch_list, review
    TO authenticated_user_role;

-- 3. Quyền của Quản trị viên Nội dung (content_admin_role):
GRANT SELECT, INSERT, UPDATE, DELETE
    ON TABLE genre, content, movie, tv_series, season, episode, content_genre
    TO content_admin_role;

GRANT SELECT
    ON TABLE review, vw_content_catalog_summary
    TO content_admin_role;